<?php
namespace App\Http\Controllers\Api;
use App\Http\Controllers\Controller;use App\Models\Category;use App\Models\InventoryStock;use App\Models\Product;use App\Models\StockAdjustment;use App\Models\StockTransfer;use App\Models\Unit;use App\Support\BusinessAccess;use Illuminate\Http\Request;use Illuminate\Support\Facades\DB;
class InventoryController extends Controller{
 public function units(Request $r){return response()->json(['data'=>Unit::where('business_id',BusinessAccess::id($r))->orderBy('name')->get()]);}
 public function storeUnit(Request $r){BusinessAccess::requireRole($r,['owner','manager','super_admin']);$data=$r->validate(['name'=>['required','string','max:50'],'symbol'=>['required','string','max:20']]);return response()->json(['data'=>Unit::create([...$data,'business_id'=>BusinessAccess::id($r)])],201);}
 public function categories(Request $r){return response()->json(['data'=>Category::where('business_id',BusinessAccess::id($r))->orderBy('name')->get()]);}
 public function storeCategory(Request $r){BusinessAccess::requireRole($r,['owner','manager','super_admin']);$business=BusinessAccess::id($r);$data=$r->validate(['name'=>['required','string','max:100'],'parent_id'=>['nullable','integer','exists:categories,id']]);if(!empty($data['parent_id']))Category::where('business_id',$business)->findOrFail($data['parent_id']);return response()->json(['data'=>Category::create([...$data,'business_id'=>$business])],201);}
 public function products(Request $r){$q=Product::with(['category','unit'])->where('business_id',BusinessAccess::id($r));if($r->filled('search'))$q->where(fn($x)=>$x->where('name','like','%'.$r->search.'%')->orWhere('sku','like','%'.$r->search.'%')->orWhere('barcode',$r->search));return response()->json(['data'=>$q->latest()->paginate($r->integer('per_page',20))]);}
 public function storeProduct(Request $r){BusinessAccess::requireRole($r,['owner','manager','super_admin']);$business=BusinessAccess::id($r);$data=$r->validate(['name'=>['required','string','max:160'],'sku'=>['required','string','max:60'],'barcode'=>['nullable','string','max:80'],'category_id'=>['nullable','integer','exists:categories,id'],'unit_id'=>['nullable','integer','exists:units,id'],'purchase_price'=>['nullable','numeric','min:0'],'selling_price'=>['required','numeric','min:0']]);abort_if(Product::where('business_id',$business)->where('sku',$data['sku'])->exists(),422,'SKU already exists in this business.');if(!empty($data['category_id']))Category::where('business_id',$business)->findOrFail($data['category_id']);if(!empty($data['unit_id']))Unit::where('business_id',$business)->findOrFail($data['unit_id']);return response()->json(['data'=>Product::create([...$data,'business_id'=>$business])->load(['category','unit'])],201);}
 public function updateProduct(Request $r,Product $product){BusinessAccess::requireRole($r,['owner','manager','super_admin']);$business=BusinessAccess::id($r);abort_unless($product->business_id===$business,403);$data=$r->validate(['name'=>['sometimes','string','max:160'],'barcode'=>['nullable','string','max:80'],'category_id'=>['nullable','integer','exists:categories,id'],'unit_id'=>['nullable','integer','exists:units,id'],'purchase_price'=>['nullable','numeric','min:0'],'selling_price'=>['sometimes','numeric','min:0'],'is_active'=>['sometimes','boolean']]);if(!empty($data['category_id']))Category::where('business_id',$business)->findOrFail($data['category_id']);if(!empty($data['unit_id']))Unit::where('business_id',$business)->findOrFail($data['unit_id']);$product->update($data);return response()->json(['data'=>$product->fresh(['category','unit'])]);}
 public function stocks(Request $r){$branch=$r->validate(['branch_id'=>['required','integer','exists:branches,id']])['branch_id'];BusinessAccess::branch($r,$branch);return response()->json(['data'=>InventoryStock::with('product.category','product.unit')->where('branch_id',$branch)->whereHas('product',fn($q)=>$q->where('business_id',BusinessAccess::id($r)))->get()]);}
 public function updateStock(Request $r,InventoryStock $stock){BusinessAccess::requireRole($r,['owner','manager','super_admin']);BusinessAccess::branch($r,$stock->branch_id);abort_unless($stock->product()->where('business_id',BusinessAccess::id($r))->exists(),403);$stock->update($r->validate(['reorder_level'=>['required','numeric','min:0']]));return response()->json(['data'=>$stock->fresh('product')]);}
 public function adjust(Request $r){BusinessAccess::requireRole($r,['owner','manager','super_admin']);$business=BusinessAccess::id($r);$data=$r->validate(['branch_id'=>['required','integer','exists:branches,id'],'product_id'=>['required','integer','exists:products,id'],'quantity'=>['required','numeric','not_in:0'],'reason'=>['required','string','max:100'],'notes'=>['nullable','string']]);BusinessAccess::branch($r,$data['branch_id']);Product::where('business_id',$business)->findOrFail($data['product_id']);return DB::transaction(function()use($data,$r){$stock=InventoryStock::where('branch_id',$data['branch_id'])->where('product_id',$data['product_id'])->lockForUpdate()->firstOrCreate(['branch_id'=>$data['branch_id'],'product_id'=>$data['product_id']],['quantity'=>0,'reorder_level'=>0]);abort_if($stock->quantity+$data['quantity']<0,422,'Insufficient stock.');$stock->increment('quantity',$data['quantity']);$adjustment=StockAdjustment::create([...$data,'user_id'=>$r->user()->id]);return response()->json(['data'=>['adjustment'=>$adjustment,'stock'=>$stock->fresh()]],201);});}
 public function transfer(Request $r){BusinessAccess::requireRole($r,['owner','manager','super_admin']);$business=BusinessAccess::id($r);$data=$r->validate(['from_branch_id'=>['required','integer','different:to_branch_id','exists:branches,id'],'to_branch_id'=>['required','integer','exists:branches,id'],'product_id'=>['required','integer','exists:products,id'],'quantity'=>['required','numeric','gt:0'],'notes'=>['nullable','string']]);BusinessAccess::branch($r,$data['from_branch_id']);BusinessAccess::branch($r,$data['to_branch_id']);Product::where('business_id',$business)->findOrFail($data['product_id']);return DB::transaction(function()use($data,$r){$from=InventoryStock::where('branch_id',$data['from_branch_id'])->where('product_id',$data['product_id'])->lockForUpdate()->firstOrCreate(['branch_id'=>$data['from_branch_id'],'product_id'=>$data['product_id']],['quantity'=>0,'reorder_level'=>0]);abort_if($from->quantity<$data['quantity'],422,'Insufficient stock at source branch.');$from->decrement('quantity',$data['quantity']);$to=InventoryStock::where('branch_id',$data['to_branch_id'])->where('product_id',$data['product_id'])->lockForUpdate()->firstOrCreate(['branch_id'=>$data['to_branch_id'],'product_id'=>$data['product_id']],['quantity'=>0,'reorder_level'=>0]);$to->increment('quantity',$data['quantity']);return response()->json(['data'=>StockTransfer::create([...$data,'user_id'=>$r->user()->id,'status'=>'completed'])],201);});}
}
